<?php
fscanf(STDIN, "%d %d %d %d", $n, $m, $a, $b);

$dp = array_fill(0, $n + 1, 0);

for ($i = 1; $i <= $n; $i++) {
    $dp[$i] = $dp[$i - 1] + $a;
    $prev = max(0, $i - $m);
    if ($dp[$prev] + $b < $dp[$i]) {
        $dp[$i] = $dp[$prev] + $b;
    }
}

echo $dp[$n] . "\n";
